// Accepts an object (from the Structured Output Parser) or a string; attaches the critique to the draft for Content QA.
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
};
const prev = $('Parse Brief').first().json;
const draft = $('Copywriter').first().json.output;
let cr = parseAgentJson($input.first().json.output);
if (!cr || typeof cr !== 'object') cr = { score: null, verdict: 'unknown', problems: [], revision_instructions: '', strengths: [], banned_phrases_found: [], unsupported_claims: [], missing_brief_items: [], parse_failed: true };
cr.problems = Array.isArray(cr.problems) ? cr.problems.slice(0, 12) : [];
return [{ json: { ...prev, output: draft, critique: cr } }];

// Which competitor pages came back blocked, empty or too thin? Those get a second attempt through Jina's browser engine + proxy pool.
const meta = $('Pick Top 6').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const blocked = [];
res.forEach((j, i) => {
  const info = meta[i] || {};
  if (!info.url) return;
  const raw = String(j.page_text || j.data || j.body || '');
  const words = raw.split(/\s+/).filter(Boolean).length;
  const bad = !!j.error || !raw || /captcha|cloudflare ray id|access denied|just a moment|enable javascript and cookies|verify you are human|attention required/i.test(raw.slice(0, 1500)) || words < 120;
  if (bad) blocked.push({ index: i, url: info.url, domain: info.domain, reason: j.error ? 'request error' : (!raw ? 'empty response' : (words < 120 ? 'too little text' : 'bot protection')) });
});
return [{ json: { blocked, blocked_count: blocked.length, pages_ok: res.length - blocked.length } }];

// Turns the raw competitor pages into (1) a per-competitor digest for the analyst, (2) a TERM MODEL — the words and
// phrases most top pages share (what the topic is "made of"), (3) the questions competitors answer, (4) the statistics
// they cite, plus the SERP features from the same search. Longer excerpts than v3 (9,000 chars kept per page).
let input;
try { input = $('Collect Client Pages').first().json; } catch (e) { input = $('Collect Site URLs').first().json; }
const meta = $('Pick Top 6').all();
const pages = $('Read Competitor Pages').all().map(i => ({ json: i.json || {} }));
// pages that were blocked on the first read and recovered through the browser-engine retry replace the blocked ones
let retried_pages = 0;
try {
  const retried = $('Retry Blocked Pages').all();
  const items = $('Blocked Page Items').all().map(i => i.json);
  retried.forEach((r, k) => {
    const idx = items[k] ? items[k].index : null; const rj = r.json || {}; const raw = String(rj.page_text || rj.data || '');
    if (idx == null || rj.error || raw.split(/\s+/).length < 120 || /captcha|cloudflare ray id|access denied|just a moment|verify you are human/i.test(raw.slice(0, 1500))) return;
    pages[idx] = { json: { ...rj, retried: true } }; retried_pages++;
  });
