const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="utf-8"><title>${esc(head.keyword)} — Keyword Ladder Plan</title>
<!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View></w:WordDocument></xml><![endif]-->
<style>${css}</style></head>
<body>${parts.join('\n')}</body></html>`;
const safe = String(head.keyword || 'keyword').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const fileName = 'keyword-ladder-' + safe + '-' + today + '.doc';
// drop the large intermediate fields; keep what delivery, the store rows and the page runs need
const slim = { ...d, site_text: undefined, client_pages: undefined, existing_page_text: undefined, competitor_digest: undefined, term_digest: undefined, term_model: undefined,
  competitors_summary: undefined, competitor_questions: undefined, stats_seen: undefined, facts: undefined, extra_questions: undefined, serp_digest: undefined,
  site_urls: undefined, internal_link_candidates: undefined, research: undefined, competitor_analysis: undefined, serp_features: undefined, result_html: undefined };
return [{
  json: { ...slim, run_ledger, request_id: d.request_id || null, report_type: 'Keyword Ladder Plan', file_name: fileName, ladder_id: L.ladder_id, site_urls_count: (d.site_urls || []).length,
    qa_summary: 'Ladder plan: ' + num(st.pages_total) + ' pages, ' + (L.write_now || []).length + ' written now' },
  binary: { data: { data: Buffer.from('﻿' + html, 'utf8').toString('base64'), mimeType: 'application/msword', fileName, fileExtension: 'doc' } }
}];

// Copy of the report HTML named index.html for the PDF renderer (Gotenberg requires that exact file name)
const item = $input.first();
const doc = (item.binary || {}).data;
if (!doc) return [item];
return [{ json: item.json, binary: { data: doc, html: { ...doc, fileName: 'index.html', mimeType: 'text/html', fileExtension: 'html' } } }];

// Merge the PDF (when the renderer succeeded) with the original Word-compatible file. Never fails the run.
const src = $('Prepare PDF Ladder').first();
const got = $input.first() || {};
const pdf = got.binary && got.binary.pdf && !(got.json && got.json.error) ? got.binary.pdf : null;
const name = String(src.json.file_name || 'report.doc').replace(/\.doc$/i, '') + '.pdf';
const binary = {};
if (src.binary && src.binary.data) binary.data = src.binary.data;
if (pdf) binary.pdf = { ...pdf, fileName: name, mimeType: 'application/pdf', fileExtension: 'pdf' };
return [{ json: { ...src.json, pdf_ready: !!pdf, pdf_file_name: pdf ? name : null, pdf_error: pdf ? null : String((got.json && got.json.error && (got.json.error.message || got.json.error)) || 'renderer returned no file').slice(0, 200) }, binary }];

// One row per ladder page for the "seo_ladders" Data Table (the rank tracker reads these every week).
const d = $('Attach PDF Ladder').first().json;
const L = d.ladder || {};
const pages = [...(L.rungs || []).flatMap(r => (r.pages || []).map(p => ({ ...p, months: r.months }))), L.top].filter(Boolean);
const now = new Date().toISOString();
const writing = new Set((L.write_now || []).map(w => w.keyword));
return pages.map(p => ({ json: {
  ladder_id: String(L.ladder_id || ''), domain: String(L.domain || d.domain || ''), head_keyword: String((L.head || {}).keyword || d.keyword || ''),
  rung: Number(p.rung) || 4, page_no: Number(p.page_no) || 0, keyword: String(p.keyword || ''), supporting: (p.supporting || []).join(', '),
  page_type: String(p.page_type || ''), target_url: String(p.target_url || ''), page_exists: !!p.exists, status: writing.has(p.keyword) ? 'writing' : 'planned',
  months: Array.isArray(p.months) ? p.months.join('-') : '', start_date: now, country: String(d.country || ''), location_code: Number(d.location_code) || 0,
  language_code: String(d.language_code || 'en'), email: String(d.email || ''), callback_url: String(d.callback_url || ''), request_id: String(d.request_id || '')
} }));

// Restores the ladder report item (json + PDF/Word binaries) after the Data Table steps and records whether the rows were stored.
const src = $('Attach PDF Ladder').first();
let stored_rows = 0, store_error = null;
try {
  const rows = $('Save Ladder Rows').all();
  stored_rows = rows.filter(i => i.json && !i.json.error).length;
  const err = rows.find(i => i.json && i.json.error);
  if (err) store_error = String((err.json.error && (err.json.error.message || err.json.error.description)) || err.json.error).slice(0, 200);
} catch (e) { store_error = 'Data Table step did not run: ' + String(e.message || e).slice(0, 160); }
return [{ json: { ...src.json, stored_rows, store_error, tracking_registered: stored_rows > 0 }, binary: src.binary || {} }];

// Starts one content run (mode "keyword") per page in write_now, as separate executions through API Entry.
// Each run delivers its own PDF/Word by e-mail and/or callback, tagged with the ladder id and rung.
const d = $input.first().json; const L = d.ladder || {};
const GOAL = { leads: 'Get leads and enquiries', sales: 'Sell online', traffic: 'Rank and educate (traffic)', brand: 'Build the brand' };
const n = Math.min(3, Math.max(1, Number(d.pages_now) || 1));
return (L.write_now || []).slice(0, n).map(p => ({ json: { body: {
  mode: 'keyword', keyword: p.keyword, page_type: p.page_type || 'Service Page', country: d.country, domain: d.domain,
  business: d.business || '', customers: d.audience || '', business_facts: d.business_facts || '', cta: d.cta || '', tone: d.tone || '', goal: GOAL[d.goal] || d.goal || '',
  receive: ['Keyword Report', 'Page Content'], existing_page_url: p.exists ? p.target_url : '',
  email: d.email || '', callback_url: d.callback_url || '', request_id: d.request_id || '', client_ip: 'ladder:' + (L.ladder_id || ''),
  force_content: true, ladder_id: L.ladder_id || '', ladder_rung: p.rung, ladder_head: (L.head || {}).keyword || d.keyword, ladder_page_no: p.page_no,
  ladder_links: (p.links_to || []).map(l => ({ url: l.url, path: String(l.url).replace(/^https?:\/\/[^\/]+/i, '') || '/', role: l.role, keyword: l.keyword, planned: true })),
  wordpress_url: d.wordpress_url || ''
} } }));

// API delivery for ladder mode: the plan (JSON + PDF + Word) goes to the callback. The pages written now arrive later
// as separate callbacks (stage: content) carrying the same request_id and ladder_id.
const item = $input.first(); const d = item.json; const L = d.ladder || {}; const bin = item.binary || {};
const b64 = async (prop, b) => { try { const buf = await this.helpers.getBinaryDataBuffer(0, prop); if (buf && buf.length) return buf.toString('base64'); } catch (e) {} return (b && b.data && String(b.data).length > 100) ? b.data : null; };
const pdfData = bin.pdf ? await b64('pdf', bin.pdf) : null;
const docData = bin.data ? await b64('data', bin.data) : null;
const page = (p) => ({ page_no: p.page_no, rung: p.rung, keyword: p.keyword, supporting: p.supporting, page_type: p.page_type, intent: p.intent, volume: p.volume, total_volume: p.total_volume, kd: p.kd, traffic_potential: p.traffic_potential, your_position: p.your_position, exists: p.exists, target_url: p.target_url, status: p.status, links_to: p.links_to, months: p.months || null });
return [{ json: {
  status: 'completed', stage: 'ladder_plan', request_id: d.request_id || null, execution_id: $execution.id, ladder_id: L.ladder_id || d.ladder_id || null,
  keyword: d.keyword, domain: d.domain, country: d.country, goal: L.goal, head: L.head || null, feasibility: L.feasibility || null,
  rungs: (L.rungs || []).map(r => ({ rung: r.rung, label: r.label, months: r.months, available_keywords: r.available, pages: (r.pages || []).map(page) })),
  top_page: L.top ? page(L.top) : null, link_map: L.link_map || [], timeline: L.timeline || [], write_now: L.write_now || [], pages_started: (L.write_now || []).slice(0, Number(d.pages_now) || 1).map(w => w.keyword),
  later: L.later || [], requirements: L.requirements || [], stats: L.stats || null, notes: L.notes || [], tracker: L.tracker || null,
  tracking_registered: !!d.tracking_registered, stored_rows: d.stored_rows || 0, store_error: d.store_error || null, run_ledger: d.run_ledger || null, emailed_to: d.email || null,
  pdf: pdfData ? { data: pdfData, fileName: bin.pdf.fileName || d.pdf_file_name, mimeType: 'application/pdf' } : null,
  file: docData ? { data: docData, fileName: bin.data.fileName || d.file_name, mimeType: 'application/msword' } : null,
  callback_url: d.callback_url || ''
} }];

// Discovery choice step (form only): the user's pick replaces the system's pipeline keyword.
const base = $('Build Keyword Strategy').first().json;
const ans = $input.first().json || {};
const key = Object.keys(ans).find(k => /keyword/i.test(k));
const choice = String(key ? ans[key] : '').trim();
const ks = JSON.parse(JSON.stringify(base.keyword_strategy || {}));
const sug = JSON.parse(JSON.stringify(base.keyword_suggestions || {}));
const systemPick = ks.pipeline_keyword ? ks.pipeline_keyword.keyword : null;
if (!choice || /^let the system/i.test(choice)) return [{ json: { ...base, chosen_by: 'system', chosen_keyword: systemPick } }];
const m = choice.match(/^(\d+)\.\s*(.+?)(\s+·.*)?$/);
const text = (m ? m[2] : choice.split(' · ')[0]).toLowerCase().trim();
const idx = m ? Number(m[1]) - 1 : -1;
const list = ks.priority || [];
const pick = (list[idx] && list[idx].keyword === text) ? list[idx] : (list.find(k => k.keyword === text) || (ks.keywords || []).find(k => k.keyword === text));
if (!pick) return [{ json: { ...base, chosen_by: 'system', chosen_keyword: systemPick, choice_error: 'Choice not recognised: ' + choice } }];
const chosen = { ...pick, why: pick.why || 'chosen by you' };
ks.pipeline_keyword = chosen;
sug.recommended = [{ ...chosen, reason: 'chosen by you' }, ...(sug.recommended || []).filter(r => r.keyword !== chosen.keyword)];
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = String(base.result_html || '').replace('<b>Where to start:</b>', '<b>Your choice:</b> "' + esc(chosen.keyword) + '" — ' + esc(chosen.why) + '<br><b>System suggestion:</b>');
return [{ json: { ...base, keyword_strategy: ks, keyword_suggestions: sug, result_html: html, chosen_by: 'user', chosen_keyword: chosen.keyword } }];

// Discover mode: the extras the user ticked (keyword report / page content for the chosen keyword, site audit or full
// report) run as SEPARATE executions through API Entry. A form completion page ends the execution it is in, so the
// download page can only be the last step; API callers still get one callback per stage with the same request_id.
const d = $input.first().json;
const GOAL = { leads: 'Get leads and enquiries', sales: 'Sell online', traffic: 'Rank and educate (traffic)', brand: 'Build the brand' };
const common = { country: d.country, domain: d.domain || '', business: d.business || '', customers: d.audience || '', business_facts: d.business_facts || '', cta: d.cta || '', tone: d.tone || '',
  goal: GOAL[d.goal] || d.goal || '', email: d.email || '', callback_url: d.callback_url || '', request_id: d.request_id || $execution.id, client_ip: 'discover:' + $execution.id };
const out = [];
if (d.include_content || d.include_seo_report) {
  const ks = d.keyword_suggestions || {};
  const pick = (ks.recommended || [])[0] || (ks.easy_wins || [])[0] || null;
  if (pick && pick.keyword) {
    const intent = pick.intent || 'commercial';
    const receive = []; if (d.include_seo_report) receive.push('Keyword Report'); if (d.include_content) receive.push('Page Content');
    out.push({ json: { body: { mode: 'keyword', keyword: pick.keyword, page_type: pick.page_type || (intent === 'informational' ? 'Blog Post' : 'Service Page'), ...common, receive,
      chosen_keyword_reason: pick.why || pick.reason || ('Highest-scoring ' + intent + ' keyword from the research'), chosen_by: d.chosen_by || 'system', pipeline_source: 'discover' } } });
  }
}
if (d.include_audit) out.push({ json: { body: { mode: 'audit', report_type: d.include_full_report ? 'Full SEO Report' : 'Site Audit (technical issues only)', competitors: (d.competitors || []).join(', '), ...common } } });
return out;

// Audit requested through the form: the audit itself runs as a separate execution (API Entry, e-mail delivery) so the
// "Your audit has started" page can be shown at once — a form completion page ends the execution it is in.
const d = $input.first().json;
return [{ json: { body: { mode: 'audit', domain: d.domain, country: d.country, report_type: d.include_full_report ? 'Full SEO Report' : 'Site Audit (technical issues only)',
  competitors: (d.competitors || []).join(', '), email: d.email || '', callback_url: d.callback_url || '', request_id: d.request_id || $execution.id, client_ip: 'form-audit:' + $execution.id } } }];

